        "items": [
          {
            "field": "description",
            "fieldtype": "jira",
            "from_string": "As a Developer, \nI want a reusable {{global/country-currency-selector}} React component built to the Zimmermann Design System 2026 spec, \nso that it can be consumed across storefronts to allow shoppers to select their shipping country, currency, and optionally language.\n\n----\n\nThe component is a right-anchored slide-in drawer. It accepts props to control which optional sections render. It does not own redirect logic — that will be covered in [https://zimmermannworkboard.atlassian.net/browse/SFCC-817|https://zimmermannworkboard.atlassian.net/browse/SFCC-817|smart-link] ",
            "to_string": "As a Developer, \nI want a reusable {{global/country-currency-selector}} React component built to the Zimmermann Design System 2026 spec, \nso that it can be consumed across storefronts to allow shoppers to select their shipping country, currency, and optionally language.\n\n----\n\nThe component is a right-anchored slide-in drawer. It accepts props to control which optional sections render. It does not own redirect logic — that will be covered in [https://zimmermannworkboard.atlassian.net/browse/SFCC-688|https://zimmermannworkboard.atlassian.net/browse/SFCC-688|smart-link] or [https://zimmermannworkboard.atlassian.net/browse/SFCC-817|https://zimmermannworkboard.atlassian.net/browse/SFCC-817|smart-link] "
          }
