        "items": [
          {
            "field": "Acceptance Criteria",
            "fieldtype": "custom",
            "from_string": "*Remove*\n\n# Given a Shopper views a line item in the cart, when they click Remove, then the item is immediately removed from the cart and the order summary updates accordingly.\n# Given the cart had only one item and the Shopper removes it, when the removal completes, then the empty cart state is displayed as per [SFCC-277].\n# Given a Shopper has a line item in the cart with a quantity greater than 1, when they click Remove, then all units of that line item are removed from the cart in a single action.\n\n*Wishlist*\n\n# Given an Authenticated Shopper clicks Move to Wishlist on a line item with a quantity of 1, when the action completes, then the item is moved to their wishlist, removed from the cart, and a success banner is displayed at the top of the cart page “[Product Name] has been moved to your wishlist” - (see [SFCC-405] for banner component behaviour).\n# Given an Authenticated Shopper has a quantity greater than 1 of a line item in their cart and clicks Move to Wishlist, when the action completes, then all units are removed from the cart, a single SKU is saved to the wishlist, and a success banner is displayed at the top of the cart page “[Product Name] has been moved to your wishlist” - (see [SFCC-405] for banner component behaviour).\n# {color:#36b37e}Given an Authenticated Shopper clicks Move to Wishlist on a line item that already exists in their wishlist, when the action is attempted, then a page-level error banner is displayed reading “Selected product already exists in wishlist and the item remains in the cart” (see {color}[SFCC-404]{color:#36b37e} for banner component behaviour). - {color}{color:#ff5630}Check with Kiera whether this is the correct state.{color}\n# Given a Guest Shopper clicks Move to Wishlist on a line item, when the action is taken, then they are redirected to the login/registration page and the item remains in the cart until they authenticate.\n# Given a Guest Shopper authenticates after being redirected, when they return to the cart, then the item is moved to their wishlist, removed from the cart, and a success banner is displayed at the top of the cart page “[Product Name] has been moved to your wishlist” - (see [SFCC-405] for banner component behaviour).",
            "to_string": "*Remove*\n\n# Given a Shopper views a line item in the cart, when they click Remove, then the item is immediately removed from the cart, the cart drawer item count decrements accordingly (e.g. Bag • 3 becomes Bag • 2), and the order summary totals update accordingly.\n# Given the cart had only one item and the Shopper removes it, when the removal completes, then the empty cart state is displayed as per [SFCC-277].\n# Given a Shopper has a line item in the cart with a quantity greater than 1, when they click Remove, then all units of that line item are removed from the cart in a single action.\n\n*Wishlist*\n\n# Given an Authenticated Shopper clicks Move to Wishlist on a line item with a quantity of 1, when the action completes, then the item is moved to their wishlist, removed from the cart, the cart drawer item count decrements accordingly, the order summary totals update, and a page-level success banner is displayed reading [Product Name] has been moved to your wishlist” - (see [SFCC-405] for banner component behaviour).\n# Given an Authenticated Shopper has a quantity greater than 1 of a line item in their cart and clicks Move to Wishlist, when the action completes, then all units are removed from the cart, a single SKU is saved to the wishlist, the cart drawer item count decrements by the full quantity removed, the order summary totals update, and the page-level success banner displays [Product Name] has been moved to your wishlist” - (see [SFCC-405] for banner component behaviour).\n# {color:#36b37e}Given an Authenticated Shopper clicks Move to Wishlist on a line item that already exists in their wishlist, when the action is attempted, then a page-level error banner is displayed reading “Selected product already exists in wishlist and the item remains in the cart” (see {color}[SFCC-404]{color:#36b37e} for banner component behaviour). - {color}{color:#ff5630}Check with Kiera whether this is the correct state.{color}\n# Given a Guest Shopper clicks Move to Wishlist on a line item, when the action is taken, then they are redirected to the login/registration page and the item remains in the cart until they authenticate.\n# Given a Guest Shopper authenticates after being redirected, when they return to the cart, then the item is moved to their wishlist, removed from the cart, and a success banner is displayed at the top of the cart page “[Product Name] has been moved to your wishlist” - (see [SFCC-405] for banner component behaviour).",
            "from_id": "",
            "to_id": ""
          }
        ],
