        "items": [
          {
            "field": "description",
            "fieldtype": "jira",
            "from_string": "As a Shopper, I want to remove an item from my cart or move it to my wishlist directly from the cart page, so that I can manage my bag without losing products I may want to purchase later.\n\nBoth \"Remove\" and \"Wishlist\" actions appear as underlined links beneath each line item, consistent with Figma designs for desktop and mobile. All cart and wishlist state is managed by SFCC.",
            "to_string": "As a Shopper, I want to remove an item from my cart or move it to my wishlist directly from the cart page, so that I can manage my bag without losing products I may want to purchase later.\n\nBoth \"Remove\" and \"Wishlist\" actions appear as underlined links beneath each line item, consistent with Figma designs for desktop and mobile. All cart and wishlist state is managed by SFCC.\n\n*Image for reference (figma leading):*\n\n!image-20260802-234338.png|width=875,alt=\"image-20260802-234338.png\"!"
          }
