        "items": [
          {
            "field": "description",
            "fieldtype": "jira",
            "from_string": "As a Shopper, I want to be clearly informed when I've reached the maximum purchase quantity for a product in my bag, so that I understand why I can't increase the quantity further.\n\nThe maximum SKU purchase quantity is configured globally in Business Manager and enforced at the variant level (per size/colour). When a shopper has reached the maximum allowed SKU limit, the + will be disabled, and error messaging will be displayed to the customer. The checkout should never be blocked.",
            "to_string": "*As a* Shopper, I want to be clearly informed when I have reached the maximum purchase quantity for a product in my bag, so that I understand why I cannot add more and can still proceed to checkout.\n\nThis story covers the *behaviour and interaction between multiple cart components* when the maximum purchase quantity is reached — it is not a component build story. The following components must be developed before this story can be implemented end to end:\n\n* *Cart Item component* — renders the quantity stepper and inline warning message \n* *Page-level banner* — renders the banner at the top of the cart drawer"
          }
        ],
        "author": {
          "display_name": "Isabel Chaloner",
          "name": "Isabel Chaloner",
          "email": "isabel.chaloner@accenture.com",
          "avatar_url": "https://secure.gravatar.com/avatar/1e5a0df80fa413e572a441e3890e6a12?d=https%3A%2F%2Favatar-management--avatars.us-west-2.prod.public.atl-paas.net%2Finitials%2FIC-6.png"
