            "fieldtype": "custom",
            "from_string": "Depends on SFCC-196 (PDP – Maximum Purchase Quantity).",
            "to_string": "Depends on SFCC-268 — global default configuration must be in place before cart enforcement can be tested end-to-end.",
            "from_id": "",
