            "field": "Dependency",
            "fieldtype": "custom",
            "from_string": "@Zimmermann: confirm whether guest and authenticated users are both taken directly to SFCC checkout entry without an intermediate login step - on Magento international users are directed to a separate login page first.\n@Zimmermann: confirm expected behaviour when a 100% discount promotion is applied and cart total is zero - should Checkout CTA remain enabled?\n@Accenture Dev: confirm how domestic vs international storefront detection works - is it storefront-based, IP-based, or address-based?\n@Accenture Dev: confirm whether a loading state is required on the Checkout CTA and duration.\nCross-epic dependency: SFCC-63 (Global-e Checkout Handoff) for international routing. SFCC-271 for quantity/inventory error disable states. SFCC-282 for OOS disable state. SFCC-277 for empty cart state.",
            "to_string": "",
            "from_id": "",
            "to_id": ""
          }
        ],
        "author": {
          "display_name": "Isabel Chaloner",
          "name": "Isabel Chaloner",
          "email": "isabel.chaloner@accenture.com",
          "avatar_url": "https://secure.gravatar.com/avatar/1e5a0df80fa413e572a441e3890e6a12?d=https%3A%2F%2Favatar-management--avatars.us-west-2.prod.public.atl-paas.net%2Finitials%2FIC-6.png"
